import assert from 'node:assert/strict';

// Fixed event time makes the generated bytes independent of wall time.
// Scenarios explicitly disable age retention and query without a time window.
export function corpus(seed, count, run) {
  let state = seed >>> 0;
  return Array.from({ length: count }, (_, seq) => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    const status = state % 10 === 0 ? 503 : 200;
    return {
      env: 'experiment', service: ['web', 'auth', 'app'][state % 3],
      timestamp: '2026-01-01T12:00:00Z', level: status === 503 ? 'error' : 'info',
      experiment_run: run, experiment_seq: seq, status,
      host: `host-${state % 8}`, latency_ms: state % 300,
      message: `synthetic-event-${seq} status=${status}`,
    };
  });
}

export function verifyRows(response, events) {
  assert.equal(response.truncated, false, 'query was truncated');
  const columns = response.columns.map(c => c.name);
  const seq = columns.indexOf('experiment_seq');
  const status = columns.indexOf('status');
  assert.ok(seq >= 0 && status >= 0, 'expected sequence and status columns');
  const actual = response.rows.map(row => [row[seq], row[status]]).sort((a, b) => a[0] - b[0]);
  assert.deepEqual(actual, events.map(e => [e.experiment_seq, e.status]), 'missing, duplicate, or changed events');
}

export function percentile(values, fraction) {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.max(0, Math.ceil(sorted.length * fraction) - 1)] ?? null;
}
